public class Patch implements Opcodes{public static void main(String[]a)throws Exception{int hooks=0;try(ZipFile z=new ZipFile(a[0]);ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();byte[] b=z.getInputStream(e).readAllBytes();if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);boolean changed=false;for(var m:c.methods){if(c.name.equals("dev/zomboid/hordes/BarrierBreakGoal")&&m.name.equals("start")){for(var n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList x=new InsnList();for(String f:new String[]{"mob","pos","original"}){x.add(new VarInsnNode(ALOAD,0));x.add(new FieldInsnNode(GETFIELD,c.name,f,f.equals("mob")?"Lnet/minecraft/world/entity/Mob;":f.equals("pos")?"Lnet/minecraft/core/BlockPos;":"Lnet/minecraft/world/level/block/state/BlockState;"));}x.add(new MethodInsnNode(INVOKESTATIC,c.name,"glass","(Lnet/minecraft/world/level/block/state/BlockState;)Z",false));x.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/sounds/ActionSounds","barrier","(Ljava/lang/Object;Ljava/lang/Object;Z)V",false));m.instructions.insertBefore(n,x);hooks++;changed=true;}}if(c.name.equals("dev/zomboid/hordes/BarrierBreakGoal")&&m.name.equals("tick")){for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode f&&f.name.equals("destroyBlock")&&f.desc.endsWith(")Z")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new FieldInsnNode(GETFIELD,c.name,"original","Lnet/minecraft/world/level/block/state/BlockState;"));x.add(new MethodInsnNode(INVOKESTATIC,c.name,"glass","(Lnet/minecraft/world/level/block/state/BlockState;)Z",false));x.add(new InsnNode(IAND));for(String field:new String[]{"mob","pos"}){x.add(new VarInsnNode(ALOAD,0));x.add(new FieldInsnNode(GETFIELD,c.name,field,field.equals("mob")?"Lnet/minecraft/world/entity/Mob;":"Lnet/minecraft/core/BlockPos;"));}x.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/sounds/ActionSounds","window","(ZLjava/lang/Object;Ljava/lang/Object;)Z",false));m.instructions.insert(n,x);hooks++;changed=true;}}if(c.name.equals("dev/zomboid/hordes/ZombieCombat")&&m.name.equals("damaged")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/sounds/ActionSounds","damaged","(Ljava/lang/Object;)V",false));m.instructions.insert(x);hooks++;changed=true;}}if(changed){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();ClassNode v=new ClassNode();new ClassReader(b).accept(v,0);for(var m:v.methods)if(m.instructions.size()>0)new Analyzer<>(new BasicVerifier()).analyze(v.name,m);}}out.putNextEntry(new ZipEntry(e.getName()));out.write(b);out.closeEntry();}}if(hooks!=3)throw new Exception("hooks "+hooks);System.out.println("Patched "+hooks+" event hooks");}}
